const HOP_BY_HOP = new Set(['connection', 'keep-alive', 'proxy-authenticate', 'proxy-authorization'[REDACTED] 'te', 'trailer', 'transfer-encoding', 'upgrade', 'host', 'content-length']);
const DEFAULT_VERCEL_HOST = 'pujan-portfolio-sandy.vercel.app';

function requestHeader(req, name) {
  const value = req.headers?.[name];
  return Array.isArray(value) ? value[0] : value;
}

function allowedVercelHosts() {
  return new Set(String(process.env.PORTFOLIO_ALLOWED_VERCEL_HOSTS || DEFAULT_VERCEL_HOST)
    .split(',')
    .map((host) => host.trim().toLowerCase())
    .filter(Boolean));
}

function requestHost(req) {
  return String(requestHeader(req, 'host') || '').split(',')[0].trim().split(':')[0].toLowerCase();
}

function requestBody(req) {
  if (['GET', 'HEAD'].includes(req.method)) return undefined;
  if (req.body == null) return undefined;
  if (Buffer.isBuffer(req.body)) return req.body;
  if (typeof req.body === 'string') return req.body;
  return JSON.stringify(req.body);
}

function forwardedHeaders(req, token) {
  const headers = {};
  for (const [key, value] of Object.entries(req.headers || {})) {
    if (HOP_BY_HOP.has(key.toLowerCase()) || value == null) continue;
    headers[key] = Array.isArray(value) ? value.join(', ') : value;
  }
  headers['x-portfolio-proxy-token'] = token;
  return headers;
}

function requestedPath(req) {
  const url = new URL(req.url || '/', 'https://portfolio.local');
  const pathValue = Array.isArray(req.query?.path) ? req.query.path.join('/') : req.query?.path;
  const path = String(pathValue || '').replace(/^\/+/, '');
  if (!path) return '/health';
  url.searchParams.delete('path');
  const suffix = url.searchParams.toString();
  return `/${path}${suffix ? `?${suffix}` : ''}`;
}

export default async function handler(req, res) {
  if (!allowedVercelHosts().has(requestHost(req))) {
    return res.status(403).json({ error: 'vercel_host_required' });
  }
  const origin = String(requestHeader(req, 'origin') || '');
  if (origin && origin !== 'https://pujan-portfolio-sandy.vercel.app') {
    return res.status(403).json({ error: 'vercel_origin_required' });
  }
  const backend = String(process.env.PORTFOLIO_BACKEND_URL || '').replace(/\/+$/, '');
  const token = String(process.env.PORTFOLIO_PROXY_TOKEN || '');
  if (!backend.startsWith('https://') || !token) {
    return res.status(503).json({error: 'proxy_not_configured'});
  }

  try {
    const response = await fetch(`${backend}${requestedPath(req)}`, {
      method: req.method,
      headers: forwardedHeaders(req, token),
      body: requestBody(req),
    });
    res.status(response.status);
    for (const [key, value] of response.headers) {
      if (!HOP_BY_HOP.has(key.toLowerCase())) res.setHeader(key, value);
    }
    const payload = Buffer.from(await response.arrayBuffer());
    res.setHeader('content-length', payload.length);
    return res.end(payload);
  } catch (error) {
    return res.status(502).json({error: 'backend_unavailable',message: 'The portfolio service is temporarily unavailable.'});
  }
}
